env.snapshot:
git archive origin/main | tar -x -C $SCR/tree; cp <the files above> $SCR/tree/...; ln -s $R/node_modules $R/.env $SCR/tree/; perl -0pi -e 's/renderer: \{
    plugins:/renderer: {
    cacheDir: resolve(__dirname, ".vite-cache"),
    server: { port: 5199, strictPort: true },
    plugins:/' $SCR/tree/electron.vite.config.ts; (cd $SCR/tree && swift build -c debug --package-path native/afm-bridge)
